services:
  app:
    build: .
    ports: ["8080:3000"]
    environment: { DATABASE_URL: "postgres://postgres:dev@db:5432/postgres" }
    depends_on: { db: { condition: service_healthy } }
  db:
    image: postgres:18
    environment: { POSTGRES_PASSWORD: dev }
    volumes: ["pgdata:/var/lib/postgresql"]
    healthcheck: { test: ["CMD", "pg_isready", "-U", "postgres"], interval: 5s }
volumes: { pgdata: {} }

# Dockerfile: exec form ให้ node เป็น PID 1 และได้รับสัญญาณโดยตรง
